#include <math.h>
#include <string.h>

#define MAXN 64

static void orthonormalize(double *Q, int n, int p) {
    for (int j = 0; j < p; ++j) {
        for (int k = 0; k < j; ++k) {
            double d = 0.0;
            for (int i = 0; i < n; ++i) d += Q[i*p+k]*Q[i*p+j];
            for (int i = 0; i < n; ++i) Q[i*p+j] -= d*Q[i*p+k];
        }
        double nrm = 0.0;
        for (int i = 0; i < n; ++i) nrm += Q[i*p+j]*Q[i*p+j];
        nrm = sqrt(nrm);
        if (nrm < 1e-300) {
            for (int i = 0; i < n; ++i) Q[i*p+j] = (i == j ? 1.0 : 0.0);
            continue;
        }
        for (int i = 0; i < n; ++i) Q[i*p+j] /= nrm;
    }
}

static int qr_mgs(const double *Z, int n, int p, double *Q) {
    for (int j = 0; j < p; ++j) {
        for (int i = 0; i < n; ++i) Q[i*p+j] = Z[i*p+j];
        for (int k = 0; k < j; ++k) {
            double d = 0.0;
            for (int i = 0; i < n; ++i) d += Q[i*p+k]*Q[i*p+j];
            for (int i = 0; i < n; ++i) Q[i*p+j] -= d*Q[i*p+k];
        }
        double nrm = 0.0;
        for (int i = 0; i < n; ++i) nrm += Q[i*p+j]*Q[i*p+j];
        nrm = sqrt(nrm);
        if (nrm < 1e-280) return 1;
        for (int i = 0; i < n; ++i) Q[i*p+j] /= nrm;
    }
    return 0;
}

/* eigenvalues/eigenvectors of 2x2 B (row major). returns chosen eigenvalue (lr,li)
   and eigenvector u (ur[2], ui[2]). */
static void eig2(const double *B, double *lr, double *li, double *ur, double *ui) {
    double a = B[0], b = B[1], c = B[2], d = B[3];
    double tr = a + d;
    double det = a*d - b*c;
    double disc = tr*tr - 4.0*det;
    if (disc >= 0.0) {
        double s = sqrt(disc);
        double l1 = 0.5*(tr + s);
        double l2 = 0.5*(tr - s);
        double l;
        if (fabs(l1) >= fabs(l2)) l = l1; else l = l2;
        *lr = l; *li = 0.0;
        /* vector: (b, l-a), or (l-d, c) when first is zero */
        double x = b, y = l - a;
        if (fabs(x) + fabs(y) < 1e-280) {
            x = l - d; y = c;
        }
        if (fabs(x) + fabs(y) < 1e-280) {
            x = 1.0; y = 0.0;
        }
        double nr = sqrt(x*x + y*y);
        ur[0] = x/nr; ui[0] = 0.0;
        ur[1] = y/nr; ui[1] = 0.0;
    } else {
        double s = sqrt(-disc);
        double re = 0.5*tr;
        double im = 0.5*s; /* choose +i */
        *lr = re; *li = im;
        /* (b, l-a) */
        double xr = b, xi = 0.0;
        double yr = re - a, yi = im;
        double nr = sqrt(xr*xr + xi*xi + yr*yr + yi*yi);
        if (nr < 1e-280) {
            /* (l-d, c) */
            xr = re - d; xi = im; yr = c; yi = 0.0;
            nr = sqrt(xr*xr + xi*xi + yr*yr + yi*yi);
        }
        if (nr < 1e-280) { xr=1.0; xi=0.0; yr=0.0; yi=0.0; nr=1.0; }
        ur[0]=xr/nr; ui[0]=xi/nr;
        ur[1]=yr/nr; ui[1]=yi/nr;
    }
}

/* returns 0 on success, 1 if need fallback */
int dominant_eig(const double *A, int n, double *lr, double *li, double *vr, double *vi) {
    if (n == 1) {
        *lr = A[0]; *li = 0.0; vr[0] = 1.0; vi[0] = 0.0;
        return 0;
    }
    if (n > MAXN) return 1;
    const int p = 2;
    double Q[MAXN*2], Z[MAXN*2];
    /* deterministic pseudo-random initial subspace */
    for (int j = 0; j < p; ++j) {
        for (int i = 0; i < n; ++i) {
            double x = sin((double)(i+1)*12.9898 + (double)(j+1)*78.233) * 43758.5453;
            x = x - floor(x);
            Q[i*p+j] = x - 0.5;
        }
    }
    orthonormalize(Q, n, p);
    double anorm = 0.0;
    for (int i = 0; i < n*n; ++i) anorm += A[i]*A[i];
    anorm = sqrt(anorm);
    double tol = 1e-10 * (anorm > 1.0 ? anorm : 1.0);
    const int maxit = 300;
    double best_r = 1e300, best_lr=0, best_li=0, best_vr[MAXN], best_vi[MAXN];
    for (int it = 0; it < maxit; ++it) {
        /* Z = A*Q */
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < p; ++j) {
                const double *row = A + i*n;
                double s = 0.0;
                for (int k = 0; k < n; ++k) s += row[k] * Q[k*p+j];
                Z[i*p+j] = s;
            }
        }
        /* B = Q^T Z */
        double B[4];
        for (int r = 0; r < 2; ++r) {
            for (int c = 0; c < 2; ++c) {
                double s = 0.0;
                for (int k = 0; k < n; ++k) s += Q[k*2+r] * Z[k*2+c];
                B[r*2+c] = s;
            }
        }
        double lur, lui, ur[2], ui[2];
        eig2(B, &lur, &lui, ur, ui);
        /* r = Z u - lambda Q u */
        double rnorm = 0.0, vnorm = 0.0;
        double vv_r[MAXN], vv_i[MAXN];
        for (int i = 0; i < n; ++i) {
            double qr = Q[i*2]*ur[0] + Q[i*2+1]*ur[1];
            double qi = Q[i*2]*ui[0] + Q[i*2+1]*ui[1];
            double zu_r = Z[i*2]*ur[0] + Z[i*2+1]*ur[1];
            double zu_i = Z[i*2]*ui[0] + Z[i*2+1]*ui[1];
            /* lambda * q */
            double lq_r = lur*qr - lui*qi;
            double lq_i = lur*qi + lui*qr;
            double dr = zu_r - lq_r, di = zu_i - lq_i;
            rnorm += dr*dr + di*di;
            vnorm += qr*qr + qi*qi;
            vv_r[i] = qr; vv_i[i] = qi;
        }
        rnorm = sqrt(rnorm);
        if (rnorm < best_r) {
            best_r = rnorm;
            best_lr = lur; best_li = lui;
            memcpy(best_vr, vv_r, n*sizeof(double));
            memcpy(best_vi, vv_i, n*sizeof(double));
        }
        if (rnorm <= tol * sqrt(vnorm)) {
            double vn = sqrt(vnorm);
            for (int i = 0; i < n; ++i) { vr[i] = vv_r[i]/vn; vi[i] = vv_i[i]/vn; }
            *lr = lur; *li = lui;
            return 0;
        }
        if (qr_mgs(Z, n, p, Q)) return 1;
    }
    /* return best? Better to signal fallback. */
    return 1;
}
