#include <math.h>
#include <string.h>
#include <dlfcn.h>
#include <stdio.h>

#define MAXN 64
typedef long long blasint;
typedef void (*dgeev_t)(char*,char*,blasint*,double*,blasint*,double*,double*,double*,blasint*,double*,blasint*,double*,blasint*,blasint*);
static dgeev_t dgeev_fn = 0;
int init_lapack(const char *path) {
    void *h = dlopen(path, RTLD_NOW|RTLD_GLOBAL);
    if (!h) return -1;
    dgeev_fn = (dgeev_t)dlsym(h, "scipy_dgeev_64_");
    if (!dgeev_fn) dgeev_fn = (dgeev_t)dlsym(h, "dgeev_");
    return dgeev_fn ? 0 : -2;
}

/* complex LU with partial pivoting, in-place A (n*n row major) */
static int clu(double *ar, double *ai, int n, int *piv) {
    for (int k=0;k<n;k++) {
        int p=k; double best=ar[k*n+k]*ar[k*n+k]+ai[k*n+k]*ai[k*n+k];
        for (int i=k+1;i<n;i++){double m=ar[i*n+k]*ar[i*n+k]+ai[i*n+k]*ai[i*n+k]; if(m>best){best=m;p=i;}}
        piv[k]=p;
        if (p!=k) for(int j=0;j<n;j++){double t=ar[k*n+j];ar[k*n+j]=ar[p*n+j];ar[p*n+j]=t;t=ai[k*n+j];ai[k*n+j]=ai[p*n+j];ai[p*n+j]=t;}
        double dr=ar[k*n+k], di=ai[k*n+k];
        double den=dr*dr+di*di;
        if (den < 1e-300) { ar[k*n+k]=1e-12; den=1e-24; dr=1e-12; di=0; }
        for (int i=k+1;i<n;i++){
            double nr=ar[i*n+k], ni=ai[i*n+k];
            double qr=(nr*dr+ni*di)/den, qi=(ni*dr-nr*di)/den;
            ar[i*n+k]=qr; ai[i*n+k]=qi;
            for(int j=k+1;j<n;j++){
                double xr=ar[i*n+j], xi=ai[i*n+j];
                double yr=ar[k*n+j], yi=ai[k*n+j];
                ar[i*n+j]=xr-qr*yr+qi*yi;
                ai[i*n+j]=xi-qr*yi-qi*yr;
            }
        }
    }
    return 0;
}
static void csolve(double *ar,double *ai,int n,int *piv,double *br,double *bi,double *xr,double *xi){
    for(int i=0;i<n;i++){int p=piv[i];double t=br[i];br[i]=br[p];br[p]=t;t=bi[i];bi[i]=bi[p];bi[p]=t;}
    for(int i=0;i<n;i++){
        double sr=br[i], si=bi[i];
        for(int j=0;j<i;j++){sr-=ar[i*n+j]*br[j]-ai[i*n+j]*bi[j]; si-=ar[i*n+j]*bi[j]+ai[i*n+j]*br[j];}
        br[i]=sr;bi[i]=si;
    }
    for(int i=n-1;i>=0;i--){
        double sr=br[i],si=bi[i];
        for(int j=i+1;j<n;j++){sr-=ar[i*n+j]*br[j]-ai[i*n+j]*bi[j]; si-=ar[i*n+j]*bi[j]+ai[i*n+j]*br[j];}
        double dr=ar[i*n+i],di=ai[i*n+i],den=dr*dr+di*di;
        xr[i]=(sr*dr+si*di)/den; xi[i]=(si*dr-sr*di)/den;
    }
}

int dominant_lapack(const double *A, int n, double *lr, double *li, double *vr, double *vi) {
    if (!dgeev_fn) return 1;
    if (n>MAXN) return 1;
    double a[MAXN*MAXN], wr[MAXN], wi[MAXN], vl[MAXN*MAXN], vrr[MAXN*MAXN], work[2048];
    memcpy(a,A,n*n*sizeof(double));
    blasint nn=n, lda=n, ldvl=1, ldvr=1, lwork=2048, info=0;
    char jl='N', jr='N';
    dgeev_fn(&jl,&jr,&nn,a,&lda,wr,wi,vl,&ldvl,vrr,&ldvr,work,&lwork,&info);
    if (info!=0) return 2;
    int idx=0; double best=-1;
    for(int i=0;i<n;i++){double m=wr[i]*wr[i]+wi[i]*wi[i]; if(m>best){best=m;idx=i;}}
    double lamr=wr[idx], lami=wi[idx];
    /* inverse iteration on A - lam I, complex */
    double ar[MAXN*MAXN], ai[MAXN*MAXN];
    double anorm=0; for(int i=0;i<n*n;i++) anorm+=A[i]*A[i]; anorm=sqrt(anorm);
    double eps=1e-14*anorm;
    for(int i=0;i<n;i++)for(int j=0;j<n;j++){ar[i*n+j]=A[i*n+j]; ai[i*n+j]=0;}
    for(int i=0;i<n;i++){ar[i*n+i]-=lamr; ai[i*n+i]-=lami+eps;}
    int piv[MAXN]; clu(ar,ai,n,piv);
    double xr[MAXN],xi[MAXN],br[MAXN],bi[MAXN];
    for(int i=0;i<n;i++){xr[i]=sin((i+1)*1.234+0.7); xi[i]=cos((i+1)*0.987+0.2);}
    for(int it=0;it<3;it++){
        double xn=0; for(int i=0;i<n;i++) xn+=xr[i]*xr[i]+xi[i]*xi[i]; xn=sqrt(xn);
        for(int i=0;i<n;i++){br[i]=xr[i]/xn;bi[i]=xi[i]/xn;}
        csolve(ar,ai,n,piv,br,bi,xr,xi);
    }
    /* Rayleigh quotient and normalize */
    double xnorm=0; for(int i=0;i<n;i++) xnorm+=xr[i]*xr[i]+xi[i]*xi[i]; xnorm=sqrt(xnorm);
    for(int i=0;i<n;i++){xr[i]/=xnorm;xi[i]/=xnorm;}
    double rr=0,ri=0;
    for(int i=0;i<n;i++){
        double yr=0,yi=0; for(int j=0;j<n;j++){yr+=A[i*n+j]*xr[j]; yi+=A[i*n+j]*xi[j];}
        double xc_r=xr[i], xc_i=-xi[i];
        rr+=xc_r*yr-xc_i*yi; ri+=xc_r*yi+xc_i*yr;
    }
    *lr=rr;*li=ri;
    for(int i=0;i<n;i++){vr[i]=xr[i];vi[i]=xi[i];}
    return 0;
}
