#include <math.h>
#include <string.h>

#define MAXN 16

static double cabs2(double r, double i){ return r*r+i*i; }

/* real Hessenberg reduction, in place row-major */
static void hessenberg(double *A, int n) {
    double v[MAXN], tmp[MAXN];
    for (int k=0;k<n-2;k++) {
        int m=n-k-1;
        double nrm=0;
        for(int i=k+1;i<n;i++) nrm += A[i*n+k]*A[i*n+k];
        nrm=sqrt(nrm);
        if (nrm==0.0) continue;
        double alpha = (A[(k+1)*n+k] >= 0.0 ? -nrm : nrm);
        for(int i=k+1;i<n;i++) v[i]=A[i*n+k];
        v[k+1]-=alpha;
        double vn=0;
        for(int i=k+1;i<n;i++) vn+=v[i]*v[i];
        if (vn==0.0) continue;
        double f=2.0/vn;
        /* left: rows k+1..n-1, cols k..n-1 */
        for(int j=k;j<n;j++){
            double dot=0;
            for(int i=k+1;i<n;i++) dot += v[i]*A[i*n+j];
            dot*=f;
            for(int i=k+1;i<n;i++) A[i*n+j]-=dot*v[i];
        }
        /* right: rows 0..n-1, cols k+1..n-1 */
        for(int i=0;i<n;i++){
            double dot=0;
            for(int j=k+1;j<n;j++) dot += A[i*n+j]*v[j];
            dot*=f;
            for(int j=k+1;j<n;j++) A[i*n+j]-=dot*v[j];
        }
        for(int i=k+2;i<n;i++) A[i*n+k]=0.0;
        A[(k+1)*n+k]=alpha;
    }
}

static void csqrtd(double x,double y,double *rr,double *ri){
    if (x==0.0 && y==0.0){*rr=0;*ri=0;return;}
    double mag=hypot(x,y);
    if (x>=0.0){
        double r=sqrt(0.5*(mag+x));
        double i=y/(2.0*r);
        *rr=r;*ri=i;
    } else {
        double i=sqrt(0.5*(mag-x));
        if (y<0.0) i=-i;
        double r=y/(2.0*i);
        *rr=r;*ri=i;
    }
}

static void qr_step(double *tr,double *ti,int n,int k,double mur,double mui){
    double br[MAXN*MAXN], bi[MAXN*MAXN];
    double cr[MAXN], sr[MAXN], si[MAXN];
    for(int i=0;i<k;i++) for(int j=0;j<k;j++){
        br[i*k+j]=tr[i*n+j]; bi[i*k+j]=ti[i*n+j];
    }
    for(int i=0;i<k;i++){ br[i*k+i]-=mur; bi[i*k+i]-=mui; }
    for(int j=0;j<k-1;j++){
        double xr=br[j*k+j], xi=bi[j*k+j];
        double yr=br[(j+1)*k+j], yi=bi[(j+1)*k+j];
        double c,sr_,si_;
        if (cabs2(xr,xi) < 1e-300){
            if (cabs2(yr,yi) < 1e-300){ c=1.0; sr_=0.0; si_=0.0; }
            else { double ay=hypot(yr,yi); c=0.0; sr_=yr/ay; si_=-yi/ay; }
        } else {
            double den=xr*xr+xi*xi;
            double tr_=(yr*xr+yi*xi)/den;
            double ti_=(yi*xr-yr*xi)/den;
            double mag2=tr_*tr_+ti_*ti_;
            c=1.0/sqrt(1.0+mag2);
            sr_=c*tr_; si_=-c*ti_;
        }
        cr[j]=c; sr[j]=sr_; si[j]=si_;
        for(int col=j;col<k;col++){
            double ur=br[j*k+col], ui=bi[j*k+col];
            double vr=br[(j+1)*k+col], vi=bi[(j+1)*k+col];
            br[j*k+col] = c*ur + sr_*vr - si_*vi;
            bi[j*k+col] = c*ui + sr_*vi + si_*vr;
            br[(j+1)*k+col] = -sr_*ur - si_*ui + c*vr;
            bi[(j+1)*k+col] =  si_*ur - sr_*ui + c*vi;
        }
        br[(j+1)*k+j]=0.0; bi[(j+1)*k+j]=0.0;
    }
    for(int j=0;j<k-1;j++){
        double c=cr[j], sr_=sr[j], si_=si[j];
        for(int row=0;row<k;row++){
            double ur=br[row*k+j], ui=bi[row*k+j];
            double vr=br[row*k+j+1], vi=bi[row*k+j+1];
            br[row*k+j] = c*ur + sr_*vr + si_*vi;
            bi[row*k+j] = c*ui + sr_*vi - si_*vr;
            br[row*k+j+1] = -sr_*ur + si_*ui + c*vr;
            bi[row*k+j+1] = -si_*ur - sr_*ui + c*vi;
        }
    }
    for(int i=0;i<k;i++){ br[i*k+i]+=mur; bi[i*k+i]+=mui; }
    for(int i=0;i<k;i++) for(int j=0;j<k;j++){
        if (i>j+1){ br[i*k+j]=0.0; bi[i*k+j]=0.0; }
        tr[i*n+j]=br[i*k+j]; ti[i*n+j]=bi[i*k+j];
    }
}

static int custom_eigs(const double *A, int n, double *wr, double *wi){
    double H[MAXN*MAXN];
    memcpy(H,A,n*n*sizeof(double));
    hessenberg(H,n);
    double tr[MAXN*MAXN], ti[MAXN*MAXN];
    for(int i=0;i<n*n;i++){ tr[i]=H[i]; ti[i]=0.0; }
    double anorm=0; for(int i=0;i<n*n;i++) anorm+=A[i]*A[i]; anorm=sqrt(anorm);
    int k=n, total=0;
    while(k>1){
        double a_r=tr[(k-2)*n+k-2], a_i=ti[(k-2)*n+k-2];
        double d_r=tr[(k-1)*n+k-1], d_i=ti[(k-1)*n+k-1];
        double sub=hypot(tr[(k-1)*n+k-2], ti[(k-1)*n+k-2]);
        double scale=fabs(a_r)+fabs(a_i)+fabs(d_r)+fabs(d_i)+anorm;
        if (sub <= 1e-13*scale){
            wr[k-1]=d_r; wi[k-1]=d_i; k--; continue;
        }
        if (total > 300) return 1;
        double b_r=tr[(k-2)*n+k-1], b_i=ti[(k-2)*n+k-1];
        double c_r=tr[(k-1)*n+k-2], c_i=ti[(k-1)*n+k-2];
        /* eigenvalues of [[a,b],[c,d]] */
        double trr=a_r+d_r, tri=a_i+d_i;
        double detr=a_r*d_r-a_i*d_i - (b_r*c_r-b_i*c_i);
        double deti=a_r*d_i+a_i*d_r - (b_r*c_i+b_i*c_r);
        double dr=trr*trr-tri*tri-4.0*detr;
        double di=2.0*trr*tri-4.0*deti;
        double sqr,sqi; csqrtd(dr,di,&sqr,&sqi);
        double l1r=0.5*(trr+sqr), l1i=0.5*(tri+sqi);
        double l2r=0.5*(trr-sqr), l2i=0.5*(tri-sqi);
        double e1=hypot(l1r-d_r,l1i-d_i), e2=hypot(l2r-d_r,l2i-d_i);
        double mur,mui;
        if(e1<=e2){mur=l1r;mui=l1i;} else {mur=l2r;mui=l2i;}
        qr_step(tr,ti,n,k,mur,mui);
        total++;
    }
    wr[0]=tr[0]; wi[0]=ti[0];
    return 0;
}

