    }
    double xn=0;for(int i=0;i<n;i++)xn+=xr[i]*xr[i]+xi[i]*xi[i];xn=sqrt(xn);
    for(int i=0;i<n;i++){xr[i]/=xn;xi[i]/=xn;}
    for(int i=0;i<n;i++){vr[i]=xr[i];vi[i]=xi[i];}
    return 0;
}

int dominant_custom(const double *A,int n,double *lr,double *li,double *vr,double *vi){
    if(n>MAXN) return 1;
    if(n==1){*lr=A[0];*li=0;vr[0]=1;vi[0]=0;return 0;}
    double wr[MAXN],wi[MAXN];
    if(custom_eigs(A,n,wr,wi)) return 2;
    int idx=0;double best=-1;
    for(int i=0;i<n;i++){double m=wr[i]*wr[i]+wi[i]*wi[i];if(m>best){best=m;idx=i;}}
    double lamr=wr[idx],lami=wi[idx];
    inviter(A,n,lamr,lami,vr,vi);
    /* Rayleigh quotient */
    double rr=0,ri=0;
    for(int i=0;i<n;i++){
        double yr=0,yi=0;for(int j=0;j<n;j++){yr+=A[i*n+j]*vr[j];yi+=A[i*n+j]*vi[j];}
        double cr=vr[i],ci=-vi[i];
        rr+=cr*yr-ci*yi; ri+=cr*yi+ci*yr;
    }
    *lr=rr;*li=ri;
    /* residual check */
    double rn=0,an=0,vn=0;
    for(int i=0;i<n*n;i++) an+=A[i]*A[i]; an=sqrt(an);
    for(int i=0;i<n;i++){
        double ar=0,ai=0;
        for(int j=0;j<n;j++){ar+=A[i*n+j]*vr[j]; ai+=A[i*n+j]*vi[j];}
        double dr=ar-(*lr*vr[i]-*li*vi[i]), di=ai-(*lr*vi[i]+*li*vr[i]);
        rn+=dr*dr+di*di; vn+=vr[i]*vr[i]+vi[i]*vi[i];
    }
    rn=sqrt(rn); vn=sqrt(vn);
    if(rn > 1e-7*(an*vn+1e-300)) return 3;
    return 0;
}
